insert into public.plan_templates (plan_slug, day_number, scripture_ref, prayer_focus, devotional) values
('default-21', 1, 'Joel 2:12–13', 'Return to God with your whole heart as we begin.', 'A fast starts with turning. Before we ask for anything, we come back to the One who is gracious and merciful, slow to anger and full of love.'),
('default-21', 2, 'Matthew 6:16–18', 'Pray for a hidden life with God, seen by the Father alone.', 'Fasting is not a performance. Jesus assumes we will fast, and asks only that we do it for the Father''s eyes.'),
('default-21', 3, 'Psalm 51:10–12', 'Ask God for a clean heart and a steady spirit.', 'David does not promise to do better. He asks God to create something new in him. Bring the same request today.'),
('default-21', 4, 'Isaiah 58:6–9', 'Pray for those who are burdened, hungry or alone near you.', 'The fast God chooses loosens chains and shares bread. Ask who you can serve today, and expect him to answer when you call.'),
('default-21', 5, 'Matthew 4:1–4', 'Pray to hunger for God''s word more than for bread.', 'In the wilderness Jesus answers hunger with scripture. Each pang today can become a reminder of what truly keeps us alive.'),
('default-21', 6, 'Psalm 63:1–5', 'Seek God early, and thank him for his steadfast love.', 'David writes from a dry land and finds that God''s love is better than life. Let your thirst point you to him.'),
('default-21', 7, 'Daniel 1:8–16', 'Pray for resolve to honour God in everyday choices.', 'Daniel made up his mind before the test came. A week in, renew the decision you made on day one.'),
('default-21', 8, '2 Chronicles 7:14', 'Pray for our church to humble itself, pray and seek God''s face.', 'This promise is given to a people, not only to individuals. We fast together because we need God together.'),
('default-21', 9, 'Nehemiah 1:4–11', 'Pray for our town and the places that are broken in it.', 'Nehemiah wept, fasted and prayed before he built anything. Bring the needs of your community to God before you plan.'),
('default-21', 10, 'Psalm 42:1–2', 'Tell God honestly where your soul is thirsty.', 'The psalmist does not hide his longing. Halfway through, be honest with God about how you are finding this fast.'),
('default-21', 11, 'Ezra 8:21–23', 'Pray for protection and guidance for our families and children.', 'Ezra called a fast to ask for a safe journey for the little ones. Name the people you are carrying before God.'),
('default-21', 12, 'Philippians 4:6–7', 'Bring every worry to God with thanksgiving.', 'Paul does not say our requests are small. He says to bring them all, and promises a peace that guards the heart.'),
('default-21', 13, 'Esther 4:15–16', 'Pray for courage to do what God is asking of you.', 'Esther asked her people to fast with her before she acted. Courage often grows where others are praying alongside us.'),
('default-21', 14, 'Matthew 6:9–13', 'Pray the Lord''s Prayer slowly, one line at a time.', 'Jesus gives us words when we have none. Two weeks in, let his prayer shape yours.'),
('default-21', 15, '2 Chronicles 20:3–4, 12', 'Pray about the thing you do not know how to face.', 'Jehoshaphat prays, "We do not know what to do, but our eyes are on you." That is a complete prayer.'),
('default-21', 16, 'Isaiah 40:28–31', 'Ask God to renew your strength where you are weary.', 'Those who wait on the Lord find new strength. If the fast feels long today, wait on him rather than push through alone.'),
('default-21', 17, 'Acts 13:2–3', 'Pray for those our church sends and serves, near and far.', 'The church at Antioch was worshipping and fasting when the Spirit spoke. Listen today as well as ask.'),
('default-21', 18, 'James 4:8–10', 'Draw near to God, and ask him to draw near to you.', 'The promise is simple: come close, and he comes close. Humility is the way in.'),
('default-21', 19, 'Hebrews 4:14–16', 'Come boldly to God for mercy and help in your need.', 'Jesus knows our weakness from the inside. We approach a throne of grace, not a courtroom.'),
('default-21', 20, 'Luke 18:1–8', 'Keep praying for the request you are tempted to give up on.', 'Jesus told this parable so that we would always pray and not lose heart. Bring it again today.'),
('default-21', 21, 'Romans 12:1–2', 'Offer your whole life to God as this fast ends.', 'The fast finishes, the offering continues. Ask God what should stay changed after today.');
